1: "use client";
2: 
3: import React, { createContext, useContext, useEffect, useState } from "react";
4: import { User, Session, AuthError } from "@supabase/supabase-js";
5: import { supabase } from "../utils/supabase";
6: 
7: interface AuthContextType {
8:   user: User | null;
9:   session: Session | null;
10:   loading: boolean;
11:   devMode: boolean;
12:   toggleDevMode: () => void;
13:   signIn: (
14:     email: string,
15:     password: string
16:   ) => Promise<{ error: AuthError | null }>;
17:   signUp: (
18:     email: string,
19:     password: string
20:   ) => Promise<{ error: AuthError | null }>;
21:   signOut: () => Promise<{ error: AuthError | null }>;
22:   signInWithGoogle: () => Promise<{ error: AuthError | null }>;
23:   resetPassword: (email: string) => Promise<{ error: AuthError | null }>;
24: }
25: 
26: const AuthContext = createContext<AuthContextType | undefined>(undefined);
27: 
28: export const useAuth = () => {
29:   const context = useContext(AuthContext);
30:   if (context === undefined) {
31:     throw new Error("useAuth must be used within an AuthProvider");
32:   }
33:   return context;
34: };
35: 
36: interface AuthProviderProps {
37:   children: React.ReactNode;
38: }
39: 
40: export const AuthProvider: React.FC<AuthProviderProps> = ({ children }) => {
41:   const [user, setUser] = useState<User | null>(null);
42:   const [session, setSession] = useState<Session | null>(null);
43:   const [loading, setLoading] = useState(true);
44:   const [devMode, setDevMode] = useState(process.env.NODE_ENV === 'development');
45: 
46:   const toggleDevMode = () => {
47:     setDevMode(prev => !prev);
48:   };
49: 
50:   useEffect(() => {
51:     // Get initial session
52:     const getInitialSession = async () => {
53:       const {
54:         data: { session },
55:       } = await supabase.auth.getSession();
56:       setSession(session);
57:       setUser(session?.user ?? null);
58:       setLoading(false);
59:     };
60: 
61:     getInitialSession();
62: 
63:     // Listen for auth changes
64:     const {
65:       data: { subscription },
66:     } = supabase.auth.onAuthStateChange(async (event: string, session: any) => {
67:       setSession(session);
68:       setUser(session?.user ?? null);
69:       setLoading(false);
70:     });
71: 
72:     return () => subscription.unsubscribe();
73:   }, []);
74: 
75:   const signIn = async (email: string, password: string) => {
76:     const { error } = await supabase.auth.signInWithPassword({
77:       email,
78:       password,
79:     });
80:     return { error };
81:   };
82: 
83:   const signUp = async (email: string, password: string) => {
84:     const { error } = await supabase.auth.signUp({
85:       email,
86:       password,
87:     });
88:     return { error };
89:   };
90: 
91:   const signOut = async () => {
92:     const { error } = await supabase.auth.signOut();
93:     return { error };
94:   };
95: 
96:   const signInWithGoogle = async () => {
97:    
98:     const { error } = await supabase.auth.signInWithOAuth({
99:       provider: "google",
100:       //options: {redirectTo},
101:       options: {
102:       redirectTo: `${window.location.origin}/`,
103:       }
104:     });
105:     return { error };
106:   };
107: 
108:   const resetPassword = async (email: string) => {
109:     const { error } = await supabase.auth.resetPasswordForEmail(email, {
110:       redirectTo: `${window.location.origin}/reset-password`,
111:     });
112:     return { error };
113:   };
114: 
115:   const value = {
116:     user,
117:     session,
118:     loading,
119:     signIn,
120:     signUp,
121:     signOut,
122:     signInWithGoogle,
123:     resetPassword,
124:     devMode,
125:     toggleDevMode,
126:   };
127: 
128:   return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
129: };

