428:         />
429:       )}
430:       {state.isMaintenanceImportModalOpen && (
431:         <ImportMaintenanceModal
432:           isOpen={state.isMaintenanceImportModalOpen}
433:           onClose={actions.closeMaintenanceImportModal}
434:           onImportMaintenanceRecords={actions.importMaintenanceRecords}
435:           machines={state.machines}
436:           maintenanceRecords={state.maintenanceRecords} // Pass existing maintenance records
437:           addToast={actions.addToast}
438:         />
439:       )}
440:       <ConfirmationDialog
441:         isOpen={state.confirmationDialogConfig.isOpen}
442:         onClose={actions.closeConfirmationDialog}
443:         onConfirm={actions.handleConfirm}
444:         title={state.confirmationDialogConfig.title}
445:         description={state.confirmationDialogConfig.description}
446:       />
447:       {state.isSparePartModalOpen && (
448:         <SparePartModal
449:           isOpen={state.isSparePartModalOpen}
450:           onClose={actions.closeSparePartModal}
451:           onSave={actions.saveSparePart}
452:           part={state.editingSparePart}
453:         />
454:       )}
455:       {state.isInstallationModalOpen && (
456:         <SparePartInstallationModal
457:           isOpen={state.isInstallationModalOpen}
458:           onClose={actions.closeInstallationModal}
459:           onSave={actions.saveSparePartInstallation}
460:           spareParts={state.spareParts}
461:           machines={state.machines}
462:           preselectedSparePartId={state.preselectedSparePartId}
463:         />
